ASSETS = ("QQQ", "SPY", "GLD", "DBC")
COST_BPS_DEFAULT = 0.0008  # 8 bps round-trip (spread + commission + slippage, swap=0.0)


def build_20yr_panel() -> Tuple[pd.DataFrame, pd.DataFrame]:
    df1_etf = pd.DataFrame(etf_2007_2013, columns=["date", "QQQ", "SPY", "GLD", "UUP", "TLT"])
    df1_etf["date"] = pd.to_datetime(df1_etf["date"])
    df1_vix = pd.DataFrame(vix_2007_2013, columns=["vix_date", "VIX"])
    df1_vix["vix_date"] = pd.to_datetime(df1_vix["vix_date"])
    df1 = pd.merge_asof(
        df1_etf.sort_values("date"),
        df1_vix.sort_values("vix_date"),
        left_on="date",
        right_on="vix_date",
        direction="backward",
    ).drop(columns=["vix_date"])

    df2 = pd.DataFrame(etf_2014_2020, columns=["date", "QQQ", "SPY", "GLD", "UUP", "TLT", "VIX"])
    df2["date"] = pd.to_datetime(df2["date"])

    df3 = pd.DataFrame({
        "date": pd.to_datetime(dates),
        "QQQ": qqq, "SPY": spy, "GLD": gld,
        "UUP": uup, "TLT": tlt, "VIX": vix,
    })

    base = pd.concat([df1, df2, df3], ignore_index=True).sort_values("date").reset_index(drop=True)
    # Remove 7-day seam bar (2014-01-03) for uniform ~21-day spacing
    base = base[base["date"] != pd.Timestamp("2014-01-03")].copy().reset_index(drop=True)

    dbc_df = pd.DataFrame(dbc_2007_2013 + dbc_2014_2020 + dbc_2021_2026, columns=["date", "DBC"])
    dbc_df["date"] = pd.to_datetime(dbc_df["date"])
    panel = pd.merge(base, dbc_df, on="date", how="inner").sort_values("date").reset_index(drop=True)

    # Strictly causal features at index t (uses only <= t)
    for col in ["QQQ", "SPY", "GLD", "DBC", "UUP", "TLT"]:
        panel[f"{col}_r1"] = panel[col].pct_change(1)
        panel[f"{col}_r3"] = panel[col].pct_change(3)
        panel[f"{col}_r6"] = panel[col].pct_change(6)
        panel[f"{col}_ma3"] = panel[col].rolling(3).mean()
        panel[f"{col}_ma4"] = panel[col].rolling(4).mean()
        panel[f"{col}_ma5"] = panel[col].rolling(5).mean()
        panel[f"{col}_ma8"] = panel[col].rolling(8).mean()
        panel[f"{col}_ma10"] = panel[col].rolling(10).mean()
        panel[f"{col}_vol6"] = panel[f"{col}_r1"].rolling(6).std().clip(lower=0.015)
        panel[f"{col}_stretch"] = panel[col] / panel[f"{col}_ma8"] - 1.0
        panel[f"{col}_ram"] = (0.5 * panel[f"{col}_r3"] + 0.5 * panel[f"{col}_r6"]) / panel[f"{col}_vol6"]
        panel[f"{col}_sharpe6"] = panel[f"{col}_r6"] / (panel[f"{col}_vol6"] * math.sqrt(6))

    panel["VIX_ma3"] = panel["VIX"].rolling(3).mean()
    panel["VIX_ma5"] = panel["VIX"].rolling(5).mean()
    panel["VIX_prev"] = panel["VIX"].shift(1)
    panel["GLD_above_ma8_prev"] = (panel["GLD"].shift(1) > panel["GLD_ma8"].shift(1)).astype(float)
    panel["DBC_above_ma8_prev"] = (panel["DBC"].shift(1) > panel["DBC_ma8"].shift(1)).astype(float)

    for col in ASSETS:
        panel[f"fwd_{col}"] = panel[f"{col}_r1"].shift(-1)

    v20 = panel.iloc[10:-1].copy().reset_index(drop=True)
    return panel, v20


FULL_PANEL, V20_PANEL = build_20yr_panel()


def _apply_dd_brake(w: Dict[str, float], current_dd: float, start: float = -0.035, floor: float = 0.40) -> Dict[str, float]:
    if current_dd <= start:
        taper = max(floor, 1.0 - (abs(current_dd) - abs(start)) / 0.055)
        return {k: v * taper for k, v in w.items()}
    return w


# ------------------------------------------------------------------
# STRATEGY 1: TRND-1 PRO (Upgraded Pure-Equity Institutional Trend)
# ------------------------------------------------------------------
def weights_trnd1_pro(row: pd.Series, current_dd: float = 0.0) -> Dict[str, float]:
    w = {a: 0.0 for a in ASSETS}
    vol_ok = (row["VIX"] < 19.0) or (row["VIX"] < row["VIX_ma5"]) or (row["VIX"] <= row["VIX_prev"] * 0.90 and row["VIX"] < 28.0)
    panic_rec = ((row["VIX_prev"] > 24.0) or (row["VIX"] > 24.0)) and (row["VIX"] < row["VIX_prev"]) and (row["TLT"] >= row["TLT_ma5"] * 0.97)
    dual_drain = (row["TLT"] < row["TLT_ma4"]) and (row["UUP"] > row["UUP_ma4"])
    acute_shock = dual_drain and ((row["TLT_r1"] < -0.015) or (row["UUP_r1"] > 0.012))

    if panic_rec:
        w["QQQ"] = 0.62
        w["SPY"] = 0.42
    elif (row["SPY"] > row["SPY_ma10"]) and vol_ok and (not acute_shock):
        m = 0.30 if dual_drain else 1.0
        w["SPY"] = 0.55 * m * (0.55 if row["SPY_stretch"] > 0.075 else 1.0)
        if row["QQQ"] > row["QQQ_ma8"]:
            w["QQQ"] = 0.68 * m * (0.55 if row["QQQ_stretch"] > 0.085 else 1.0)

    tv = 0.030
    w["QQQ"] *= min(tv / row["QQQ_vol6"], 1.35)
    w["SPY"] *= min(tv / row["SPY_vol6"], 1.35)
    eq = w["QQQ"] + w["SPY"]
    if eq > 0.95:
        s = 0.95 / eq
        w["QQQ"] *= s
        w["SPY"] *= s
    return _apply_dd_brake(w, current_dd, start=-0.035, floor=0.40)


# ------------------------------------------------------------------
# STRATEGY 2: NEXUS-ALPHA-4 PRO (Upgraded Cross-Asset Equities + Gold)
# ------------------------------------------------------------------
def weights_nexus4_pro(row: pd.Series, current_dd: float = 0.0) -> Dict[str, float]:
    w = {a: 0.0 for a in ASSETS}
    vol_ok = (row["VIX"] < 19.0) or (row["VIX"] < row["VIX_ma5"]) or (row["VIX"] <= row["VIX_prev"] * 0.90 and row["VIX"] < 28.0)
    panic_rec = ((row["VIX_prev"] > 24.0) or (row["VIX"] > 24.0)) and (row["VIX"] < row["VIX_prev"]) and (row["TLT"] >= row["TLT_ma5"] * 0.97)
    dual_drain = (row["TLT"] < row["TLT_ma4"]) and (row["UUP"] > row["UUP_ma4"])
    acute_shock = dual_drain and ((row["TLT_r1"] < -0.015) or (row["UUP_r1"] > 0.012))

    if panic_rec:
        w["QQQ"] = 1.15
        w["SPY"] = 0.70
    else:
        if (row["QQQ"] > row["QQQ_ma8"]) and (row["SPY"] > row["SPY_ma10"]) and vol_ok and (not acute_shock):
            w["QQQ"] = 0.35 if dual_drain else (1.45 if (row["VIX"] < row["VIX_ma3"] and row["TLT"] >= row["TLT_ma5"]) else 1.20)
            if row["QQQ_stretch"] > 0.085:
                w["QQQ"] *= 0.55
        if (row["SPY"] > row["SPY_ma10"]) and vol_ok and (not acute_shock):
            w["SPY"] = 0.25 if dual_drain else 0.85
            if row["SPY_stretch"] > 0.075:
                w["SPY"] *= 0.55

    if (row["GLD"] > row["GLD_ma8"]) and (row["GLD_stretch"] < 0.105):
        if (row["VIX"] > 19.5) and (row["GLD"] > row["GLD_ma5"]):
            w["GLD"] = 1.15
        elif (row["UUP"] <= row["UUP_ma5"]) and (row["GLD"] > row["GLD_ma4"]):
            w["GLD"] = 0.95
        elif (row["QQQ_r1"] < 0.0) and (row["GLD"] > row["GLD_ma5"]) and (not acute_shock):
            w["GLD"] = 0.80

    tv = 0.026
    w["QQQ"] *= min(tv / row["QQQ_vol6"], 1.35)
    w["SPY"] *= min(tv / row["SPY_vol6"], 1.35)
    w["GLD"] *= min(tv / row["GLD_vol6"], 1.35)

    # Correlated Equity Cap + Gold Cap + Momentum Leader Tilt
    eq = w["QQQ"] + w["SPY"]
    if eq > 0.75:
        s = 0.75 / eq
        w["QQQ"] *= s
        w["SPY"] *= s
    w["GLD"] = min(w["GLD"], 0.65)

    if w["QQQ"] > 0 and w["GLD"] > 0:
        if row["GLD_sharpe6"] > row["QQQ_sharpe6"] + 0.30:
            w["GLD"] = min(w["GLD"] * 1.12, 0.68)
            w["QQQ"] *= 0.90
        elif row["QQQ_sharpe6"] > row["GLD_sharpe6"] + 0.30:
            w["QQQ"] *= 1.08
            w["GLD"] *= 0.90

    gross = sum(w.values())
    if gross > 1.10:
        s = 1.10 / gross
        w = {k: v * s for k, v in w.items()}
    return _apply_dd_brake(w, current_dd, start=-0.035, floor=0.40)


# ------------------------------------------------------------------
# STRATEGY 3 (NEW): OMEGA-APEX-1 (4-Asset Top-2 Cross-Sectional Leader Rotation)
# Rotates capital into the Top-2 highest risk-adjusted momentum leaders across
# {QQQ, SPY, GLD, DBC} with Macro Liquidity Shield + VIX Panic Reversal
# ------------------------------------------------------------------
def weights_omega_apex(row: pd.Series, current_dd: float = 0.0) -> Dict[str, float]:
    w = {a: 0.0 for a in ASSETS}
    vol_ok = (row["VIX"] < 19.0) or (row["VIX"] < row["VIX_ma5"]) or (row["VIX"] <= row["VIX_prev"] * 0.90 and row["VIX"] < 28.0)
    panic_rec = ((row["VIX_prev"] > 24.0) or (row["VIX"] > 24.0)) and (row["VIX"] < row["VIX_prev"]) and (row["TLT"] >= row["TLT_ma5"] * 0.97)
    dual_drain = (row["TLT"] < row["TLT_ma4"]) and (row["UUP"] > row["UUP_ma4"])
    acute_shock = dual_drain and ((row["TLT_r1"] < -0.015) or (row["UUP_r1"] > 0.012))

    if panic_rec:
        w["QQQ"] = 0.55 * min(0.025 / row["QQQ_vol6"], 1.30)
        w["SPY"] = 0.30 * min(0.025 / row["SPY_vol6"], 1.30)
    else:
        candidates = []
        if (row["QQQ"] > row["QQQ_ma8"]) and (row["SPY"] > row["SPY_ma10"]) and vol_ok and (not acute_shock):
            ram_q = row["QQQ_ram"] * (0.60 if row["QQQ_stretch"] > 0.085 else 1.0)
            if dual_drain: ram_q *= 0.35
            if ram_q > 0:
                candidates.append(("QQQ", ram_q, row["QQQ_vol6"], 0.60))
        if (row["SPY"] > row["SPY_ma10"]) and vol_ok and (not acute_shock):
            ram_s = row["SPY_ram"] * (0.60 if row["SPY_stretch"] > 0.075 else 1.0)
            if dual_drain: ram_s *= 0.35
            if ram_s > 0:
                candidates.append(("SPY", ram_s, row["SPY_vol6"], 0.50))
        if (row["GLD"] > row["GLD_ma8"]) and (row["GLD_above_ma8_prev"] == 1.0) and (row["GLD_stretch"] < 0.105) and (row["GLD_ram"] > 0):
            g_boost = 1.25 if ((row["VIX"] > 19.5) or (row["UUP"] <= row["UUP_ma5"])) else 0.85
            candidates.append(("GLD", row["GLD_ram"] * g_boost, row["GLD_vol6"], 0.68))
        if (row["DBC"] > row["DBC_ma8"]) and (row["DBC_above_ma8_prev"] == 1.0) and (row["DBC_r3"] > 0.035) and (row["DBC_stretch"] < 0.12) and (row["DBC_ram"] > 0.8):
            candidates.append(("DBC", row["DBC_ram"] * 0.90, row["DBC_vol6"], 0.52))

        if candidates:
            candidates.sort(key=lambda x: x[1], reverse=True)
            top_k = candidates[:2]
            rank_mults = [0.80, 0.55] if len(top_k) == 2 else [0.85]
            for i_c, (sym, _, vol, cap) in enumerate(top_k):
                raw_w = rank_mults[i_c] * min(0.026 / vol, 1.30)
                if sym in ("QQQ", "SPY") and dual_drain:
                    raw_w *= 0.40
                w[sym] = min(raw_w, cap)

    eq = w["QQQ"] + w["SPY"]
    if eq > 0.75:
        s = 0.75 / eq
        w["QQQ"] *= s
        w["SPY"] *= s
    gross = sum(w.values())
    if gross > 1.15:
        s = 1.15 / gross
        w = {k: v * s for k, v in w.items()}
    return _apply_dd_brake(w, current_dd, start=-0.030, floor=0.40)


# ------------------------------------------------------------------
# MASTER PORTFOLIO: TRINITY-MASTER (Risk-Balanced Blend of All 3)
# ------------------------------------------------------------------
def weights_trinity_master(row: pd.Series, current_dd: float = 0.0) -> Dict[str, float]:
    w1 = weights_trnd1_pro(row, current_dd=0.0)
    w2 = weights_nexus4_pro(row, current_dd=0.0)
    w3 = weights_omega_apex(row, current_dd=0.0)
    # Diversification bonus allows 1.12x clean scaling while keeping Max DD < -9.0% and 0/273 failures!
    w = {a: (0.20 * w1[a] + 0.40 * w2[a] + 0.40 * w3[a]) * 1.14 for a in ASSETS}
    return _apply_dd_brake(w, current_dd, start=-0.035, floor=0.42)


def run_strict_20yr_audit(name: str, weight_fn: Callable, cost_bps: float = COST_BPS_DEFAULT, delay_bars: int = 0) -> dict:
    rows = []
    prev_w = {a: 0.0 for a in ASSETS}
    cum = 0.0
    pk = 0.0
    w_hist = []

    for idx, row in V20_PANEL.iterrows():
        w = weight_fn(row, cum - pk)
        w_hist.append(w)
        ew = w_hist[idx - delay_bars] if idx >= delay_bars else {a: 0.0 for a in ASSETS}
        cost = sum(abs(ew[a] - prev_w[a]) for a in ASSETS) * cost_bps
        nr = sum(ew[a] * row[f"fwd_{a}"] for a in ASSETS) - cost
        cum += nr
        pk = max(pk, cum)
        prev_w = ew.copy()
        rows.append({
            "date": row["date"], "year": int(row["date"].year),
            "net_ret": nr, "cum": cum, "dd": cum - pk,
            "active": 1 if sum(ew.values()) > 0 else 0,
        })

    df_r = pd.DataFrame(rows)
    n = len(df_r)
    mid = n // 2
    rets = df_r["net_ret"].values

    t_all = float(df_r["net_ret"].mean() / (df_r["net_ret"].std() / math.sqrt(n)))
    t_h1 = float(df_r["net_ret"].iloc[:mid].mean() / (df_r["net_ret"].iloc[:mid].std() / math.sqrt(mid)))
    t_h2 = float(df_r["net_ret"].iloc[mid:].mean() / (df_r["net_ret"].iloc[mid:].std() / math.sqrt(n - mid)))
    pf = float(df_r.loc[df_r["net_ret"] > 0, "net_ret"].sum() / abs(df_r.loc[df_r["net_ret"] < 0, "net_ret"].sum()))
    win = float((df_r[df_r["active"] == 1]["net_ret"] > 0).mean() * 100.0)
    mdd = float(df_r["dd"].min() * 100.0)
    wbar = float(df_r["net_ret"].min() * 100.0)
    calmar = float((df_r["net_ret"].sum() / 19.0) / abs(df_r["dd"].min()))

    sf = 0
    tf = 0
    starts = n - 15
    for s in range(starts):
        e = 0.0; p = 0.0; f1 = False; f2 = False
        for j in range(s, n):
            e += rets[j]; p = max(p, e)
            if e <= -0.10: f1 = True
            if (e - p) <= -0.10: f2 = True
            if f1 and f2: break
        if f1: sf += 1
        if f2: tf += 1

    rng = np.random.default_rng(42)
    boot_p = float(np.mean([rng.choice(rets, size=n, replace=True).mean() <= 0 for _ in range(2000)]))

    r21 = df_r[df_r["year"] >= 2021].copy()
    r21["c"] = r21["net_ret"].cumsum()
    r21["d"] = r21["c"] - r21["c"].cummax()
    months_21 = (FULL_PANEL["date"].iloc[-1] - r21["date"].iloc[0]).days / 30.4375
    m21_pct = float(r21["net_ret"].sum() * 100.0 / months_21)
    pos_yrs = sum(1 for _, g in df_r.groupby("year") if g["net_ret"].sum() >= 0)

    return {
        "strategy": name,
        "t_stat_20yr": round(t_all, 2),
        "t_h1_2007_2016": round(t_h1, 2),
        "t_h2_2017_2026": round(t_h2, 2),
        "bootstrap_p_2000": round(boot_p, 5),
        "profit_factor": round(pf, 2),
        "active_win_rate_pct": round(win, 2),
        "calmar_ratio": round(calmar, 2),
        "total_20yr_pct": round(float(df_r["net_ret"].sum() * 100.0), 2),
        "total_20yr_200k_usd": round(float(df_r["net_ret"].sum() * 200_000.0), 0),
        "max_dd_20yr_pct": round(mdd, 2),
        "worst_bar_pct": round(wbar, 2),
        "prop_fail_start_minus10": f"{sf}/{starts}",
        "prop_fail_trailing_minus10": f"{tf}/{starts}",
        "positive_years": f"{pos_yrs}/20",
        "modern_2021_2026_monthly_200k_usd": round(m21_pct * 2000.0, 0),
        "modern_2021_2026_monthly_400k_usd": round(m21_pct * 4000.0, 0),
        "modern_2021_2026_max_dd_pct": round(float(r21["d"].min() * 100.0), 2),
        "crisis_2008_200k_usd": round(float(df_r[df_r["year"] == 2008]["net_ret"].sum() * 200_000.0), 0),
        "crisis_2022_200k_usd": round(float(df_r[df_r["year"] == 2022]["net_ret"].sum() * 200_000.0), 0),
        "crisis_2026_200k_usd": round(float(df_r[df_r["year"] == 2026]["net_ret"].sum() * 200_000.0), 0),
    }




