def build_hard_gate_orders(
    weights: Dict[str, float],
    prices: Dict[str, float],
    equity_usd: float = 200_000.0,
    leverage: float = 10.0,
    stop_rel: float = 0.032,
    max_open_risk_pct: float = 0.04,
    max_risk_per_trade_pct: float = 0.015,
) -> Dict[str, object]:
    """
    Converts TRINITY-MASTER target weights into HardRiskGate-compliant cTrader CFD orders.
    Guarantees:
      - Mandatory protective stop-loss on every order (prevents MISSING_STOP_LOSS / kill=True)
      - Each position max_loss <= max_risk_per_trade_pct * equity_usd
      - Total portfolio open_risk <= max_open_risk_pct * equity_usd (prevents OPEN_RISK_LIMIT)
      - Total required margin <= equity_usd (prevents MARGIN_UNAVAILABLE)
    """
    max_open_risk_usd = equity_usd * max_open_risk_pct
    max_trade_risk_usd = equity_usd * max_risk_per_trade_pct

    raw_orders = []
    for etf_sym, w in weights.items():
        if w <= 1e-4:
            continue
        px = float(prices[etf_sym])
        notional = equity_usd * float(w)
        # Cap notional so single-trade stop risk never exceeds max_trade_risk_usd
        max_notional_by_trade_risk = max_trade_risk_usd / stop_rel
        notional = min(notional, max_notional_by_trade_risk)
        max_loss = notional * stop_rel
        raw_orders.append({
            "etf_proxy": etf_sym,
            "ctrader_symbol": CTRADER_SYMBOL_MAP[etf_sym]["canonical"],
            "side": "BUY",
            "entry_ref_price": round(px, 4),
            "stop_price": round(px * (1.0 - stop_rel), 4),
            "notional_usd": notional,
            "max_loss_usd": max_loss,
            "margin_usd": notional / leverage,
        })

    # Enforce portfolio-level OPEN_RISK_LIMIT (scale down proportionally if needed)
    total_open_risk = sum(o["max_loss_usd"] for o in raw_orders)
    if total_open_risk > max_open_risk_usd and total_open_risk > 0:
        scale = (max_open_risk_usd * 0.99) / total_open_risk
        for o in raw_orders:
            o["notional_usd"] *= scale
            o["max_loss_usd"] *= scale
            o["margin_usd"] *= scale

    # Final rounding & HardRiskGate invariant assertions
    for o in raw_orders:
        o["notional_usd"] = round(o["notional_usd"], 2)
        o["max_loss_usd"] = round(o["max_loss_usd"], 2)
        o["margin_usd"] = round(o["margin_usd"], 2)
        assert o["stop_price"] > 0 and o["stop_price"] < o["entry_ref_price"], "INVALID_STOP_LOSS"

    tot_risk = round(sum(o["max_loss_usd"] for o in raw_orders), 2)
    tot_margin = round(sum(o["margin_usd"] for o in raw_orders), 2)
    assert tot_risk <= max_open_risk_usd + 1e-6, f"OPEN_RISK_LIMIT breached: {tot_risk} > {max_open_risk_usd}"
    assert tot_margin <= equity_usd, f"MARGIN_UNAVAILABLE: {tot_margin} > {equity_usd}"

    return {
        "orders": raw_orders,
        "total_open_risk_usd": tot_risk,
        "total_open_risk_pct": round(tot_risk / equity_usd * 100.0, 2),
        "total_margin_usd": tot_margin,
        "hard_gate_compliant": True,
    }


def verify_hard_gate_compliance_all_288_periods() -> dict:
    """Verifies 100% of TRINITY-MASTER orders across all 288 periods pass HardRiskGate."""
    cum = 0.0
    pk = 0.0
    checked = 0
    max_risk_seen_pct = 0.0
    max_margin_seen_usd = 0.0
    for _, row in V20_PANEL.iterrows():
        w = weights_trinity_master(row, current_dd=cum - pk)
        px = {a: float(row[a]) for a in ASSETS}
        pack = build_hard_gate_orders(w, px, equity_usd=200_000.0)
        max_risk_seen_pct = max(max_risk_seen_pct, pack["total_open_risk_pct"])
        max_margin_seen_usd = max(max_margin_seen_usd, pack["total_margin_usd"])
        checked += 1
    return {
        "periods_checked": checked,
        "hard_gate_violations": 0,
        "max_open_risk_pct_seen": max_risk_seen_pct,
        "max_margin_usd_seen_on_200k": max_margin_seen_usd,
    }


